  "vocab-7": {"prompt": "¿Cómo se dice 'têtu' en español?", "promptNative": "Come si dice « têtu » in spagnolo?", "explain": "'Terco' significa testardo. 'Amable' è gentile, 'tímido' è timido, 'generoso' è generoso.", "wrongNote": "'stubborn' in spagnolo è 'terco'. Anche 'testarudo'.", "distractorNotes": {"amable": "gentile.", "tímido": "timido.", "generoso": "generoso."}},
